-- SERPA 002: source metadata and milestones. Apply after 001_initial.sql.
alter table public.tasks add column if not exists source_phase text;
alter table public.tasks add column if not exists source_area text;
alter table public.tasks add column if not exists source_owner_label text;
alter table public.tasks add column if not exists source_collaborator_label text;
alter table public.tasks add column if not exists source_dependencies text;
alter table public.tasks add column if not exists progress_percent integer not null default 0 check(progress_percent between 0 and 100);
create table if not exists public.milestones(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,source_key text not null,title text not null,target_week integer,target_date date,owner_label text,evidence_required text,status text not null default 'pending' check(status in ('pending','completed')),evidence_url text,created_at timestamptz not null default now(),unique(organization_id,source_key));
alter table public.milestones enable row level security;
create policy "milestones select" on public.milestones for select to authenticated using(public.is_org_member(organization_id));
create policy "milestones insert" on public.milestones for insert to authenticated with check(public.is_org_member(organization_id));
create policy "milestones update" on public.milestones for update to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
-- Organization must already exist. No service keys are used.
do $$ declare org uuid; begin
 select id into org from public.organizations where name='SERPA Lab Studio' order by created_at limit 1;
 if org is null then raise exception 'Create SERPA Lab Studio organization and admin membership first (see README)'; end if;

end $$;
